import React from "react";
import { Button } from "react-bootstrap";
import jsPDF from "jspdf";
import "jspdf-autotable";

const GeneraVerbale = ({ intervento }) => {
  const generaPDF = () => {
    const doc = new jsPDF();

    doc.setFontSize(16);
    doc.text("Verbale Intervento Tecnico", 20, 20);

    doc.setFontSize(12);
    doc.text(`Data: ${new Date(intervento.data.toDate()).toLocaleDateString()}`, 20, 35);
    doc.text(`Tecnico: ${intervento.tecnico}`, 20, 45);
    doc.text(`Cliente: ${intervento.clienteNome || "-"}`, 20, 55);
    doc.text(`Mezzo: ${intervento.mezzoId || "-"}`, 20, 65);
    doc.text(`Tipo: ${intervento.tipo}`, 20, 75);
    doc.text(`Urgente: ${intervento.urgente ? "Sì" : "No"}`, 20, 85);
    doc.text(`Stato: ${intervento.stato}`, 20, 95);
    doc.text("Note:", 20, 105);
    doc.text(intervento.note || "Nessuna", 20, 115, { maxWidth: 170 });

    doc.text("Firma Tecnico:", 20, 135);
    doc.text(intervento.firmaTecnico || "__________________", 20, 145);

    doc.save(`verbale_${intervento.id}.pdf`);
  };

  return (
    <Button variant="outline-dark" onClick={generaPDF}>
      🧾 Genera Verbale PDF
    </Button>
  );
};

export default GeneraVerbale;